        return try! context.fetch(fetchRequest).first
    }

    private static func createDemoTrip(context: ModelContext) {
        let demoTrip = Trip(id: DemoSeeder.demoTripID, name: "Demo Trip", startDate: Date(), endDate: Calendar.current.date(byAdding: .day, value: 5, to: Date())!, isDemo: true, createdAt: Date())

